// Created: 2026-07-24

/**
 * Workflow AgentType Advisor — PreToolUse[Workflow] Hook
 *
 * The single biggest generic-spawn bucket is Workflow-internal: agent() stages
 * default to the generic workflow subagent (3,559/30d spawns, 49% of all
 * traffic in the 2026-07 cross-account audit; M170). The Task-side advisor
 * cannot see these — Workflow spawns never pass through PreToolUse[Task].
 *
 * This hook scans the inline `script` for agent() call sites and, when none
 * of them set opts.agentType, injects an advisory reminding the author of the
 * specialist catalog mapping (mirror of
 * skills/chain-patterns/references/dynamic-workflow-patterns.md §agentType).
 *
 * Advisory ONLY — always continue:true, always permissionDecision:"allow".
 * Mixed/glue stages are legitimately generic, so this never blocks and stays
 * silent when at least one stage is already typed (author knows the option).
 *
 * @hook PreToolUse[Workflow]
 * @see https://github.com/yonatangross/orchestkit/issues/3126
 */

import type { HookContext, HookInput, HookResult } from '../../types.js';
import { outputAllowWithContext, outputSilentSuccess } from '../../lib/common.js';
import { NOOP_CTX } from '../../lib/context.js';

const HOOK_NAME = 'workflow-agenttype-advisor';

/** Stage-shape → specialist mapping, kept in sync with dynamic-workflow-patterns.md. */
const STAGE_MAP: ReadonlyArray<readonly [string, string]> = [
  ['security produce/verify stages', 'ork:security-auditor'],
  ['test generation / coverage / repair', 'ork:test-generator'],
  ['code-review dimensions over a diff', 'ork:code-quality-reviewer'],
  ['web/competitive research fan-out', 'ork:web-research-analyst'],
  ['backend/API/schema design', 'ork:backend-system-architect'],
  ['frontend component work', 'ork:frontend-ui-developer'],
];

/**
 * Count bare agent( call sites in a workflow script.
 * Word-boundary guard excludes .agent( / myagent( / "agent(" in strings well
 * enough for an advisory (false positives only produce a harmless nudge).
 */
export function countAgentCalls(script: string): number {
  const matches = script.match(/(?<![\w.])agent\s*\(/g);
  return matches ? matches.length : 0;
}

export function workflowAgentTypeAdvisor(
  input: HookInput,
  _ctx: HookContext = NOOP_CTX,
): HookResult {
  if (input.tool_name !== 'Workflow') return outputSilentSuccess();

  const toolInput = (input.tool_input ?? {}) as Record<string, unknown>;
  const script = typeof toolInput.script === 'string' ? toolInput.script : '';

  // Named/scriptPath/resume runs carry no inline script — nothing to scan.
  if (!script) return outputSilentSuccess();

  const agentCalls = countAgentCalls(script);
  if (agentCalls === 0) return outputSilentSuccess();

  // Author already reached for the catalog at least once — no nudge needed.
  if (script.includes('agentType')) return outputSilentSuccess();

  const table = STAGE_MAP.map(([shape, agent]) => `  ${shape} -> ${agent}`).join('\n');
  return outputAllowWithContext(
    `[${HOOK_NAME}] This script has ${agentCalls} agent() stage(s), none typed. ` +
      `Untyped stages run the generic workflow subagent — the largest generic-spawn bucket (M170). ` +
      `For stages with an OBVIOUS specialist owner, set opts.agentType:\n${table}\n` +
      `Mixed/cross-domain/glue stages: omit agentType — generic IS correct there. ` +
      `Use namespaced names (ork:x); bare names fail to resolve (#2371).`,
  );
}
